import React, { useState, useEffect } from "react";
import axios from "axios";

const API_BASE_URL = "http://localhost:9091";

function UserShop() {
  const [medicines, setMedicines] = useState([]);
  const [cart, setCart] = useState([]);
  const [loading, setLoading] = useState(true);

  // Fetch medicines from backend
  useEffect(() => {
    axios
      .get(`${API_BASE_URL}/api/medicines`)
      .then((res) => {
        setMedicines(res.data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching medicines:", err);
        setLoading(false);
      });
  }, []);

  // Add item to cart
  const handleAddToCart = (medicine) => {
    if (medicine.stock <= 0) {
      alert("❌ Out of stock!");
      return;
    }

    setCart((prevCart) => {
      const existing = prevCart.find((item) => item.id === medicine.id);
      if (existing) {
        // Prevent duplicate add
        return prevCart.map((item) =>
          item.id === medicine.id
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      } else {
        return [...prevCart, { ...medicine, quantity: 1 }];
      }
    });
  };

  // Optional: show total items in cart
  const totalItems = cart.reduce((acc, item) => acc + item.quantity, 0);

  if (loading) {
    return <p className="text-center text-gray-500 mt-8">Loading medicines...</p>;
  }

  return (
    <div className="p-6 max-w-6xl mx-auto">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-indigo-700">Medicine Shop</h2>
        <div className="text-gray-700 font-medium">
          🛒 Cart: <span className="font-semibold">{totalItems}</span> items
        </div>
      </div>

      {medicines.length === 0 ? (
        <p className="text-center text-gray-500">No medicines available.</p>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {medicines.map((med) => (
            <div
              key={med.id}
              className="bg-white shadow-md p-5 rounded-xl border border-gray-100 hover:shadow-lg transition"
            >
              <h3 className="text-lg font-semibold text-gray-800 mb-2">
                {med.name}
              </h3>
              <p className="text-gray-600 mb-2">{med.description}</p>
              <p className="text-green-600 font-bold mb-2">
                ₹{med.price.toFixed(2)}{" "}
                <span className="text-gray-700 font-normal">
                  (Stock: {med.stock})
                </span>
              </p>
              <button
                onClick={() => handleAddToCart(med)}
                disabled={med.stock === 0}
                className={`mt-2 w-full py-2 rounded-lg transition ${
                  med.stock > 0
                    ? "bg-indigo-600 text-white hover:bg-indigo-700"
                    : "bg-gray-400 text-white cursor-not-allowed"
                }`}
              >
                {med.stock > 0 ? "Add to Cart" : "Out of Stock"}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default UserShop;
